/**
 * The TypeScript modules the content build writes (ARCHITECTURE §5.3).
 * Each returns plain source text; outputs.ts runs it through the repo's
 * Prettier config, so `npm run format:check` passes on generated files and
 * the drift check compares formatted bytes.
 *
 * Generated modules hold data only. Ids are plain strings here, because
 * only the parse helpers in src/engine/types/ids.ts may make a branded id
 * (§3.1): the loaders and the mock decode these values on first use.
 */
import type { BuiltChoiceItem } from "./project.ts";

const json = (value: unknown) => JSON.stringify(value, null, 2);

function header(source: string, body: string[]): string {
  return [
    "/**",
    ...body.map((line) => (line === "" ? " *" : ` * ${line}`)),
    " *",
    ` * Generated by \`npm run content:build\` from ${source}. Do not edit:`,
    " * CI rebuilds it and fails on any difference (ARCHITECTURE §5.3).",
    " */",
  ].join("\n");
}

export interface ManifestPack {
  url: string;
  version: string;
  items: number;
}

export interface ManifestList {
  url: string;
  version: string;
  entities: number;
}

/** src/content/generated/manifest.ts */
export function manifestModule(input: {
  contentVersion: string;
  packs: Record<string, ManifestPack>;
  lists: Record<string, ManifestList>;
}): string {
  return [
    header("content/", [
      "The content manifest (ARCHITECTURE §5.3): the hashed URL of every",
      "practice pack and answer list the build wrote under public/content/,",
      "with item counts and the content version. The loaders fetch from it,",
      "and the service worker precaches from it (§10.7). A URL changes",
      "whenever its file does, so caches are cache-first.",
    ]),
    'import type { AnswerType, CategoryId } from "@/engine/types";',
    "",
    "export interface ManifestPack {",
    "  /** Path on this origin, under /content/packs/. */",
    "  readonly url: string;",
    "  /** The pack's version: its content hash. */",
    "  readonly version: string;",
    "  readonly items: number;",
    "}",
    "",
    "export interface ManifestList {",
    "  /** Path on this origin, under /content/lists/. */",
    "  readonly url: string;",
    "  /** The source list's version (CONTENT_GUIDE §2.10). */",
    "  readonly version: string;",
    "  readonly entities: number;",
    "}",
    "",
    "/** Changes whenever any pack or list does. */",
    `export const CONTENT_VERSION = ${json(input.contentVersion)};`,
    "",
    "/** One pack per category with active items, keyed by category id. */",
    `export const PRACTICE_PACKS: Readonly<Partial<Record<CategoryId, ManifestPack>>> = ${json(input.packs)};`,
    "",
    "/** One list per answer type, keyed by type. */",
    `export const ANSWER_LISTS: Readonly<Partial<Record<AnswerType, ManifestList>>> = ${json(input.lists)};`,
    "",
  ].join("\n");
}

/** src/content/generated/categories.ts */
export function categoriesModule(
  categories: readonly {
    id: string;
    slug: string;
    name: string;
    shortName: string;
    order: number;
  }[],
): string {
  return [
    header("content/categories.json", [
      "The 12 categories (ARCHITECTURE §3.2, CONTENT_GUIDE §1), in display",
      "order.",
    ]),
    'import type { Category } from "@/engine/types";',
    "",
    `export const CATEGORIES: readonly Category[] = ${json(categories)};`,
    "",
  ].join("\n");
}

/** src/content/generated/names.ts */
export function namesModule(names: {
  adjectives: readonly string[];
  animals: readonly string[];
}): string {
  return [
    header("content/names/adjectives.txt and animals.txt", [
      'Friendly-name parts ("Plucky Otter", ARCHITECTURE §2.1, §5.3), one',
      "word per entry, reviewed so that no pair holds a listed term",
      "(content/names/README.md).",
    ]),
    `export const NAME_ADJECTIVES: readonly string[] = ${json(names.adjectives)};`,
    "",
    `export const NAME_ANIMALS: readonly string[] = ${json(names.animals)};`,
    "",
  ].join("\n");
}

export interface CategoryPage {
  slug: string;
  intro: string | null;
  sample: BuiltChoiceItem | null;
}

/** src/content/generated/category-pages.ts */
export function categoryPagesModule(
  pages: Readonly<Record<string, CategoryPage>>,
): string {
  return [
    header("content/category-pages/ and content/practice/", [
      "Intro copy and one sample item per category for /categories/[slug]",
      "(F-CAT, ARCHITECTURE §5.3). The intro comes from",
      "content/category-pages/<slug>.json once CAT-1 writes it. The sample",
      "is the category's easiest active multiple-choice item by predicted p,",
      "ties to the lower id, so it changes only when the bank does.",
    ]),
    "export interface CategoryPageSample {",
    "  readonly id: string;",
    '  readonly format: "mc" | "tf" | "comparison";',
    "  readonly stem: string;",
    "  readonly options: readonly string[];",
    "  readonly correct: number;",
    "  readonly explanation: string;",
    "  readonly learnMore: string;",
    "}",
    "",
    "export interface CategoryPage {",
    "  readonly slug: string;",
    "  readonly intro: string | null;",
    "  readonly sample: CategoryPageSample | null;",
    "}",
    "",
    "/** Keyed by category id. */",
    `export const CATEGORY_PAGES: Readonly<Record<string, CategoryPage>> = ${json(
      Object.fromEntries(
        Object.entries(pages).map(([id, page]) => [
          id,
          {
            slug: page.slug,
            intro: page.intro,
            sample:
              page.sample === null
                ? null
                : {
                    id: page.sample.id,
                    format: page.sample.format,
                    stem: page.sample.stem,
                    options: page.sample.options,
                    correct: page.sample.correct,
                    explanation: page.sample.explanation,
                    learnMore: page.sample.learnMore,
                  },
          },
        ]),
      ),
    )};`,
    "",
  ].join("\n");
}

/** src/content/generated/moderation.ts */
export function moderationModule(moderation: {
  terms: readonly string[];
  allowlist: readonly string[];
}): string {
  return [
    header("content/safety/slur-terms.txt and allowlist.txt", [
      "The player-facing slur filter's terms (PRD §3.9.4, ARCHITECTURE",
      "§8.13), loaded lazily by src/features/nickname/filter.ts and read",
      "by the mock backend. Terms are ROT13-encoded here, as content/safety/",
      "keeps them, so none shows up in a diff, a search or a log.",
    ]),
    `export const MODERATION_TERMS_ROT13: readonly string[] = ${json(moderation.terms)};`,
    "",
    `export const MODERATION_ALLOWLIST_ROT13: readonly string[] = ${json(moderation.allowlist)};`,
    "",
  ].join("\n");
}

/** src/backend/mock/fixtures.generated.ts */
export function mockFixturesModule(data: {
  version: string;
  mysteries: readonly unknown[];
  encores: readonly unknown[];
  choices: readonly unknown[];
  roomPacks: readonly unknown[];
  schedule: readonly unknown[];
  spares: readonly unknown[];
}): string {
  return [
    header("content/fixtures/ only, never content/sealed/", [
      "The mock backend's sealed fixture content (ARCHITECTURE §5.3, §5.6,",
      "§7.4), as the built shapes of §3.2: the e2e track's mysteries,",
      "encores and sealed choice rounds, the hostable room packs, the dated",
      "Dailies and the spare sets the e2e cycle plays. Every id is fx.: the",
      "bundle scan (§5.4) finds no real sealed id here. src/backend/mock/",
      "fixtures.ts loads it lazily and decodes it on first use.",
    ]),
    `export const FIXTURE_DATA = ${json(data)};`,
    "",
  ].join("\n");
}

export const ROT13 = (value: string): string =>
  value.replace(/[a-z]/gi, (letter) => {
    const base = letter <= "Z" ? 65 : 97;
    return String.fromCharCode(
      ((letter.charCodeAt(0) - base + 13) % 26) + base,
    );
  });
